using Microsoft.AspNetCore.Components;

namespace BCP_Frontend.Components.Pages.Public_Portal
{
    public partial class Index
    {
        [Inject]
        private IProvinceService ProvinceService { get; set; } = default!;

        [Inject]
        private ICityService CityService { get; set; } = default!;

        [Inject]
        private IBloodInventoryService BloodInventoryService { get; set; } = default!;


        private List<GetAllProvinceResponse> Provinces = new();

        private List<GetAllCityResponse> AvailableCities = new();

        private List<BloodStockSearchResponse> SearchResults = new();


        private Guid? SelectedProvinceId { get; set; }

        private Guid? SelectedCityId { get; set; }

        private string SelectedBloodGroup { get; set; } = "";

        private BloodComponentType SelectedComponent { get; set; } = BloodComponentType.WholeBlood;


        protected override async Task OnInitializedAsync()
        {
            Provinces = await ProvinceService.GetAllAsync();
        }


        private async Task OnProvinceChanged(Guid? provinceId)
        {
            SelectedProvinceId = provinceId;

            SelectedCityId = null;

            AvailableCities.Clear();

            if (provinceId.HasValue)
            {
                AvailableCities =await CityService.GetByProvinceIdAsync(provinceId.Value);
            }
        }

        private async Task HandleSearch()
        {
            if (!SelectedCityId.HasValue)
                return;
            SearchResults = await BloodInventoryService.SearchBloodStockAsync(SelectedCityId.Value, SelectedBloodGroup, (int)SelectedComponent);
        }
    }
}